messages.body:
/* custom styles DEMO */
    h1, h2, h3 {
 
font-family: Verdana, Arial, sans-serif;
 
line-height: 42px;
    }
    h1 {
 font-size: 36px;
    }
    h2 {
 font-size: 26px;
    }
    h3 {
 font-size: 20px;
    }
    p {
 
font-family: Verdana, Arial, sans-serif;
 
font-size: 16px;
 
line-height: 22px;
 
visibility: visible;
    }
    b {font-weight: 700;}
 
    [class~="x_gradient"] {
 
url('https://image.orangedcx.com.mx/lib/fe3011717164057c7c1579/m/2/59bb9ad9-d154-4ba0-ba20-1f71dd02a58c.png') !important;
 
background-size: 100% 100% !important;
 
background-repeat: repeat-x !important;
    }

    .& .gradient {
 
url('https://image.orangedcx.com.mx/lib/fe3011717164057c7c1579/m/2/59bb9ad9-d154-4ba0-ba20-1f71dd02a58c.png') !important;
 
background-size: 100% 100% !important;
 
background-repeat: repeat-x !important;
    }

    body[data-outlook-cycle] .gradient {
 
url('https://image.orangedcx.com.mx/lib/fe3011717164057c7c1579/m/2/59bb9ad9-d154-4ba0-ba20-1f71dd02a58c.png') !important;
 
background-size: 100% 100% !important;
 
background-repeat: repeat-x !important;
    }
 
@media screen {
 
/* fonts */
 
@font-face {
 
font-family: 'Roboto';
 
font-style: normal;
 
